	if len(script) == 0 {
		return 0.0, fmt.Errorf("script cannot be empty")
	}
	if len(script) > maxScriptLength {
		return 0.0, fmt.Errorf("script exceeds maximum allowed length of %d characters", maxScriptLength)
	}

