	if order == nil {
		return 0.0, fmt.Errorf("order cannot be nil")
	}

	vm := goja.New()

	// Set up execution timeout using interrupt
	ctx, cancel := context.WithTimeout(context.Background(), executionTimeout)
	defer cancel()

	// Start a goroutine to interrupt the VM on timeout
	go func() {
		<-ctx.Done()
		if ctx.Err() == context.DeadlineExceeded {
			vm.Interrupt("execution timeout exceeded")
		}
	}()

	// Create a safe copy of order data to prevent modification of original
	safeOrder := make(map[string]interface{})
	for key, value := range order {
		// Only allow safe types to be passed
		if isSafeValue(value) {
			safeOrder[key] = value
		}
	}

