	vm.Set("order", safeOrder)

	// Execute the script
	result, err := vm.RunString(script)
	if err != nil {
		// Check if it was an interrupt
		if interrupted, ok := err.(*goja.InterruptedError); ok {
			return 0.0, fmt.Errorf("script execution interrupted: %v", interrupted.Value())
		}
		return 0.0, fmt.Errorf("script execution error: %w", err)
	}

	// Convert result to float64
	discount, err := toFloat64(result)
	if err != nil {
		return 0.0, err
	}

	// Validate the discount value
	if discount < 0 {
