		"couponCode":      "SAVE20",
	}

	script2 := `
		var discount = 0;

		// Membership tier discounts
		switch(membershipLevel) {
			case "platinum":
				discount = total * 0.15;
				break;
			case "gold":
				discount = total * 0.10;
				break;
			case "silver":
				discount = total * 0.05;
				break;
			default:
				discount = 0;
		}

		// First order bonus
		if (isFirstOrder) {
			discount += 10;
		}

		// Coupon code
		if (couponCode === "SAVE20") {
			discount += 20;
		}

		// Cap discount at 50% of total
		if (discount > total * 0.5) {
			discount = total * 0.5;
		}

		discount;
	`

	discount2, err := CalculateDiscount(script2, order2)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	} else {
		fmt.Printf("Example 2 - Order total: $%.2f, Discount: $%.2f\n", order2["total"], discount2)
	}

	// Example 3: Using the order object directly
	order3 := map[string]interface{}{
		"total":           75.50,
		"membershipLevel": "silver",
		"itemCount":       3,
	}

	script3 := `
		var discount = 0;

		// Access via order object
		if (order.itemCount >= 3) {
			discount = order.total * 0.08; // 8% discount for 3+ items
		}

		discount;
	`

	discount3, err := CalculateDiscount(script3, order3)
	if err != nil {
		fmt.Printf("Error: %v\n", err)
	} else {
		fmt.Printf("Example 3 - Order total: $%.2f, Items: %d, Discount: $%.2f\n", 
			order3["total"], order3["itemCount"], discount3)
	}

	// Example 4: Error handling - invalid script
	order4 := map[string]interface{}{
		"total": 100.00,
	}

	scriptInvalid := `
		this is not valid javascript!!!
	`

	_, err = CalculateDiscount(scriptInvalid, order4)
	if err != nil {
		fmt.Printf("Example 4 - Expected error caught: %v\n", err)
	}
}

